// XORReader wraps an io.Reader and performs XOR decryption on the fly
type XORReader struct {
	r   io.Reader
	key byte
}

func (xr *XORReader) Read(p []byte) (n int, err error) {
	n, err = xr.r.Read(p)
	for i := 0; i < n; i++ {
		p[i] ^= xr.key
	}
	return n, err
}

