	cfg, err := LoadConfig(configPath)
	if err != nil {
		log.Fatalf("❌ Critical config error: %v", err)
	}

	// 2. Initialize database
	dbFile := "local_cache.db"
	err = InitDB(dbFile)
	if err != nil {
		log.Fatalf("❌ Critical database error: %v", err)
	}
	defer CloseDB()

	// Ensure SQLite history doesn't bloat (run once at startup)
	CleanOldHistory()

	LogLocal("INFO", "=== Initializing IMC Audio Local Player Client ===")
	LogLocal("INFO", "Server URL: %s", cfg.ServerURL)
	LogLocal("INFO", "Store Token: %s", cfg.StoreToken)
	LogLocal("INFO", "Local Decrypter Port: %d", cfg.LocalPort)

	// Create local storage media directories if missing
	_ = os.MkdirAll("music", 0755)
	_ = os.MkdirAll("commercials", 0755)
	_ = os.MkdirAll("events", 0755)

	// Clean up temporary download artifacts if any existed from prior crashes
	files, err := filepath.Glob(filepath.Join("music", "*", "*.tmp"))
	if err == nil {
		for _, f := range files {
			_ = os.Remove(f)
		}
	}
	files, err = filepath.Glob(filepath.Join("commercials", "*.tmp"))
	if err == nil {
		for _, f := range files {
			_ = os.Remove(f)
		}
	}
	files, err = filepath.Glob(filepath.Join("events", "*.tmp"))
	if err == nil {
		for _, f := range files {
			_ = os.Remove(f)
		}
	}

	// 3. Launch HTTP decrypter and scheduler server
	go StartDecrypterServer(cfg.LocalPort)

	// 4. Launch store configuration and media sync loop
	StartSyncLoop(cfg)

	// 5. Launch Liquidsoap watchdog monitoring process
	StartLiquidsoapWatchdog(cfg)

	// 6. Launch Console interactive TUI Dashboard (blocks main thread)
	StartConsoleDashboard(cfg)
}
