"package main

import (
	"bytes"
	"io"
	"testing"
)

func TestXORReader(t *testing.T) {
	original := []byte("Hello World, this is a test audio file!")
	key := byte(0x53)

	// Encrypt
	encBuf := make([]byte, len(original))
	copy(encBuf, original)
	for i := range encBuf {
		encBuf[i] ^= key
	}

	// Decrypt using XORReader
	reader := &XORReader{
		r:   bytes.NewReader(encBuf),
		key: key,
	}
	decrypted := make([]byte, len(original))
	n, err := io.ReadFull(reader, decrypted)
	if err != nil {
		t.Fatalf("Failed to read: %v", err)
	}
	if n != len(original) {
		t.Fatalf("Expected %d bytes, got %d", len(original), n)
	}

	if !bytes.Equal(decrypted, original) {
		t.Errorf("Decrypted content does not match original. Got: %s", string(decrypted))
	}
}
"

"package main

import (
	"strings"
	"testing"
	"time"
)

func TestGetWeekdayColumn(t *testing.T) {
	tests := []struct {
		wd       time.Weekday
		expected string
	}{
		{time.Sunday, "run_on_sunday"},
		{time.Monday, "run_on_monday"},
		{time.Tuesday, "run_on_tuesday"},
		{time.Wednesday, "run_on_wednesday"},
		{time.Thursday, "run_on_thursday"},
		{time.Friday, "run_on_friday"},
		{time.Saturday, "run_on_saturday"},
	}

	for _, tc := range tests {
		actual := getWeekdayColumn(tc.wd)
		if actual != tc.expected {
			t.Errorf("For %v, expected %s, got %s", tc.wd, tc.expected, actual)
		}
	}
}

func TestFormatAnnotatedURI(t *testing.T) {
	item := PlayItem{
		ID:              "test-id",
		Type:            "music",
		DisplayName:     "Test Track",
		FileName:        "test.mp3",
		LocalPath:       `music\style-1\test.mp3`,
		DurationSeconds: 180,
		CueIn:           1.5,
		CueOut:          178.5,
		Artist:          "Test Artist",
	}

	actual := formatAnnotatedURI(item)
	expectedURI := "http://localhost:5005/play?path=music/style-1/test.mp3"

	if !strings.Contains(actual, expectedURI) {
		t.Errorf("Expected URI %s to be in formatted result, got: %s", expectedURI, actual)
	}

	if !strings.Contains(actual, `id="test-id"`) {
		t.Errorf("Expected ID annotation to be in result, got: %s", actual)
	}

	if !strings.Contains(actual, `artist="Test Artist"`) {
		t.Errorf("Expected artist annotation to be in result, got: %s", actual)
	}

	if !strings.Contains(actual, `cue_in="1.50"`) || !strings.Contains(actual, `cue_out="178.50"`) {
		t.Errorf("Expected cue annotations to be in result, got: %s", actual)
	}
}
