func isUnencryptedMP3(buf []byte) bool {
	if len(buf) < 3 {
		return false
	}
	// Check for ID3v2 tag: starts with "ID3"
	if buf[0] == 0x49 && buf[1] == 0x44 && buf[2] == 0x33 {
		return true
	}
	// Check for frame sync: starts with 0xFF, next byte top 3 bits set (0xE0)
	if buf[0] == 0xFF && (buf[1]&0xE0) == 0xE0 {
		return true
	}
	return false
}

func isXORedMP3(buf []byte) bool {
	if len(buf) < 3 {
		return false
	}
	// XOR the first 3 bytes with 0x53 and check
	b0 := buf[0] ^ 0x53
	b1 := buf[1] ^ 0x53
	b2 := buf[2] ^ 0x53

	if b0 == 0x49 && b1 == 0x44 && b2 == 0x33 {
		return true
	}
	if b0 == 0xFF && (b1&0xE0) == 0xE0 {
		return true
	}
	return false
}"

