"func downloadFile(client *http.Client, url string, token string, destPath string) error {
	req, err := http.NewRequest("GET", url, nil)
	if err != nil {
		return err
	}
	req.Header.Set("X-Store-Token", token)

	resp, err := client.Do(req)
	if err != nil {
		return err
	}
	defer resp.Body.Close()

	if resp.StatusCode != http.StatusOK {
		body, _ := io.ReadAll(resp.Body)
		return fmt.Errorf("server error (%d): %s", resp.StatusCode, string(body))
	}

	// Save to temp file first to avoid corrupted downloads on interruption
	tempFile := destPath + ".tmp"
	out, err := os.Create(tempFile)
	if err != nil {
		return err
	}
	defer func() {
		out.Close()
		_ = os.Remove(tempFile)
	}()

	// Read first 3 bytes to inspect header
	header := make([]byte, 3)
	n, errRead := io.ReadFull(resp.Body, header)
	if errRead != nil && errRead != io.ErrUnexpectedEOF && errRead != io.EOF {
		return errRead
	}

	shouldEncrypt := false
	if n > 0 && isUnencryptedMP3(header[:n]) {
		shouldEncrypt = true
	}

	// Write header (encrypting if required)
	if shouldEncrypt {
		for i := 0; i < n; i++ {
			header[i] ^= 0x53
		}
	}
	if _, err := out.Write(header[:n]); err != nil {
		return err
	}

	// Copy rest of stream
	if shouldEncrypt {
		xr := &XORReader{r: resp.Body, key: 0x53}
		_, err = io.Copy(out, xr)
	} else {
		_, err = io.Copy(out, resp.Body)
	}
	if err != nil {
		return err
	}

	out.Close()
	// Rename temp file to final destination
	return os.Rename(tempFile, destPath)
}"

