// isXORedFile inspects the file header to determine if it is XOR 0x53 encrypted
func isXORedFile(path string) (bool, error) {
	file, err := os.Open(path)
	if err != nil {
		return false, err
	}
	defer file.Close()

	header := make([]byte, 3)
	n, err := file.Read(header)
	if err != nil && err != io.EOF {
		return false, err
	}
	if n < 3 {
		return false, nil
	}

	// XOR the first 3 bytes with 0x53 and check for ID3 tag or frame sync
	b0 := header[0] ^ 0x53
	b1 := header[1] ^ 0x53
	b2 := header[2] ^ 0x53

	if b0 == 0x49 && b1 == 0x44 && b2 == 0x33 {
		return true, nil
	}
	if b0 == 0xFF && (b1&0xE0) == 0xE0 {
		return true, nil
	}
	return false, nil
}

// decryptToTempFile decrypts the XORed file to a temporary unencrypted file
func decryptToTempFile(srcPath string) (string, error) {
	fileIn, err := os.Open(srcPath)
	if err != nil {
		return "", err
	}
	defer fileIn.Close()

	tempFile := srcPath + ".dec.tmp"
	fileOut, err := os.Create(tempFile)
	if err != nil {
		return "", err
	}
	defer fileOut.Close()

	// Decrypt on the fly using XOR 0x53 reader
	xr := &XORReader{r: fileIn, key: 0x53}
	_, err = io.Copy(fileOut, xr)
	if err != nil {
		_ = os.Remove(tempFile)
		return "", err
	}

	return tempFile, nil
}

