"// CleanOldHistory prunes play history older than 48 hours to keep the database light.
func CleanOldHistory() {
	if DB == nil {
		return
	}
	cutoff := time.Now().Add(-48 * time.Hour).Format("2006-01-02 15:04:05")
	_, err := DB.Exec("DELETE FROM play_history WHERE played_at < $1", cutoff)
	if err != nil {
		LogLocal("ERROR", "Failed to clean old play history: %v", err)
	}
}

// GetCommercialFolderName maps commercial type database value to directory name matching server standards.
func GetCommercialFolderName(cType string) string {
	switch cType {
	case "INSTITUTIONAL":
		return "institutional"
	case "BLOCK_OPENING":
		return "open_blocks"
	case "BLOCK_CLOSING":
		return "close_blocks"
	case "COMMERCIAL":
		return "advertisements"
	case "OFFER":
		return "offers"
	case "EVENT":
		return "events"
	case "GENERAL_INFO":
		return "general_information"
	case "RIGHT_TIME":
		return "right_time"
	case "TEMPERATURE":
		return "temperature"
	default:
		return "advertisements"
	}
}"

