"import urllib.request
import json

url = "http://192.168.15.250:8080/api/v1/sync"
req = urllib.request.Request(url)
req.add_header("X-Store-Token", "token_1_1")

try:
    with urllib.request.urlopen(req, timeout=10) as response:
        payload = json.loads(response.read().decode("utf-8"))
        print("Keys in sync payload:", list(payload.keys()))

        media_library = payload.get("media_library", [])
        if media_library:
            print("\nFirst track keys and values:")
            for k, v in media_library[0].items():
                print(f"  {k}: {type(v).__name__} = {repr(v)}")
        else:
            print("\nNo music tracks found in media_library.")

        comms = payload.get("commercials_and_events", [])
        if comms:
            print("\nFirst commercial/event keys and values:")
            for k, v in comms[0].items():
                print(f"  {k}: {type(v).__name__} = {repr(v)}")
        else:
            print("\nNo commercials found in commercials_and_events.")
except Exception as e:
    print("Error querying sync endpoint:", e)
"

