"	// Load commercials
	col := getWeekdayColumn(t.Weekday())
	simDateStr := t.Format("2006-01-02")
	simTimeStr := t.Format("15:04:05")
	query := fmt.Sprintf(`
		SELECT id, commercial_type, name, file_name, duration_seconds, insertions_per_day, cue_in, cue_out, COALESCE(lufs, -14.0), COALESCE(lra, 0.0), COALESCE(risco_ruido, 0), COALESCE(amplify, 1.0)
		FROM commercials_and_events
		WHERE commercial_type != 'EVENT'
		  AND %s = 1
		  AND (start_date IS NULL OR start_date <= '%s')
		  AND (end_date IS NULL OR end_date >= '%s')
		  AND (start_time IS NULL OR start_time <= '%s')
		  AND (end_time IS NULL OR end_time >= '%s')`, col, simDateStr, simDateStr, simTimeStr, simTimeStr)

	rowsComm, err := DB.Query(query)
	var allComms []CommRecord
	type commExtra struct {
		LUFS       float64
		LRA        float64
		RiscoRuido int
	}
	commExtras := make(map[string]commExtra)

	if err == nil {
		defer rowsComm.Close()
		for rowsComm.Next() {
			var c CommRecord
			var ex commExtra
			var amplify sql.NullFloat64

			errScan := rowsComm.Scan(
				&c.ID, &c.Type, &c.Name, &c.FileName, &c.DurationSeconds, &c.InsertionsPerDay,
				&c.CueIn, &c.CueOut, &ex.LUFS, &ex.LRA, &ex.RiscoRuido, &amplify,
			)
			if errScan == nil {
				if amplify.Valid {
					c.Amplify = amplify.Float64
				} else {
					c.Amplify = 1.0
				}

				allComms = append(allComms, c)
				commExtras[c.ID] = ex
			}
		}
	}"

