"    <script>
        let lastActiveIndex = -1;

        function timeToSecs(timeStr) {
            const parts = timeStr.split(':');
            return parseInt(parts[0], 10) * 3600 + parseInt(parts[1], 10) * 60 + parseInt(parts[2], 10);
        }

        function switchTab(tabId) {
            document.querySelectorAll('.tab-content').forEach(el => {
                el.style.display = 'none';
            });
            document.getElementById(tabId).style.display = 'block';

            document.querySelectorAll('.tab-btn').forEach(btn => {
                btn.classList.remove('active');
            });

            if (tabId === 'tab-timeline') {
                document.getElementById('btn-tab-timeline').classList.add('active');
            } else if (tabId === 'tab-commercials') {
                document.getElementById('btn-tab-commercials').classList.add('active');
            } else if (tabId === 'tab-weekly') {
                document.getElementById('btn-tab-weekly').classList.add('active');
            }
        }

        function formatSecs(secs) {
            const h = Math.floor(secs / 3600);
            const m = Math.floor((secs % 3600) / 60);
            const s = Math.floor(secs % 60);
            return h.toString().padStart(2, '0') + ":" + m.toString().padStart(2, '0') + ":" + s.toString().padStart(2, '0');
        }"

