	if percentage <= 0 {
		return false
	}
	if percentage >= 100 {
		return true
	}
	// Use float math to avoid integer truncation issues around 0
	curr := math.Floor(float64(index) * float64(percentage) / 100.0)
	prev := math.Floor(float64(index-1) * float64(percentage) / 100.0)
