"
// recordPlayHistory saves playback history to SQLite.
// Uses expectedNextPlayTime to record the estimated real play time instead of
// the pre-fetch request time (Liquidsoap requests tracks ahead of time).
// play_status lifecycle: na_fila → tocando → executada (sequentially, never altering older records)
// The most recent item is always 'na_ponta' (the tip), previous 'na_ponta' becomes 'executada'.
func recordPlayHistory(item PlayItem) {
	if DB == nil {
		return
	}

	now := time.Now()
	playTime := now

	// If expectedNextPlayTime is set and in the future, use it as the real play time.
	// Otherwise use now (first track after startup, or gap in playback).
	if !expectedNextPlayTime.IsZero() && expectedNextPlayTime.After(now) {
		playTime = expectedNextPlayTime
	}

	// Advance the expected play time by this item's duration
	effectiveDuration := item.DurationSeconds
	if item.CueOut > 0 && item.CueOut < float64(item.DurationSeconds) {
		// Use cue_out as the real end point
		effectiveDuration = int(item.CueOut)
	}
	if item.CueIn > 0 {
		effectiveDuration -= int(item.CueIn)
	}
	if effectiveDuration <= 0 {
		effectiveDuration = item.DurationSeconds
	}

	expectedNextPlayTime = playTime.Add(time.Duration(effectiveDuration) * time.Second)

	// Sequential status: promote previous 'na_ponta' → 'executada', new item becomes 'na_ponta'
	_, _ = DB.Exec("UPDATE play_history SET play_status = 'executada' WHERE play_status = 'na_ponta'")

	_, err := DB.Exec(
		"INSERT INTO play_history (track_id, track_type, display_name, artist, played_at, duration_seconds, style_name, play_status) VALUES ($1, $2, $3, $4, $5, $6, $7, $8)",
		item.ID, item.Type, item.DisplayName, item.Artist,
		playTime.Format("2006-01-02 15:04:05"),
		effectiveDuration, item.StyleName, "na_ponta")
	if err != nil {
		LogLocal("ERROR", "Failed to write play history: %v", err)
	}
}
"

